INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-unimi-iple', 'milan-bsc-international-politics-law-economics', 'BSc International Politics, Law and Economics (IPLE)', 'u-unimi', 'bachelor', 'humanities-social', 'english', 3, 180, 'Upper secondary school diploma (at least 12 years of schooling) and English at B2 level are required. Places are capped and allocated by an admission test (the CEnT-S test replaces TOLC-E from 2026/27) — see the official programme page for the current call.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://www.unimi.it/en/education/bachelor/international-politics-law-and-economics-iple', '2026/27', 'https://www.unimi.it/en/education/bachelor/international-politics-law-and-economics-iple', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-unipd-psych', 'padova-bsc-psychological-science', 'BSc Psychological Science', 'u-unipd', 'bachelor', 'humanities-social', 'english', 3, 180, 'Secondary school diploma and English at B2 level are required. This is a limited-access programme with an online entry test in English — see the official University of Padua application page for the current call and deadlines.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://apply.unipd.it/courses/course/27-psychological-science', '2026/27', 'https://apply.unipd.it/courses/course/27-psychological-science', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-bicocca-ds', 'bicocca-msc-data-science', 'MSc Data Science', 'uni-university-of-milano-bicocca', 'master', 'computer-science-data', 'english', 2, 120, 'A Bachelor''s degree with at least 30 ECTS across statistics, computer science, mathematics and physics is required; admission includes an interview assessing preparation in computer science and statistics. Non-EU candidates who need a visa apply via apply.unimib.it — see the official programme page.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://en.unimib.it/graduate/data-science', '2026/27', 'https://en.unimib.it/graduate/data-science', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-genoa-robotics', 'genoa-msc-robotics-engineering', 'MSc Robotics Engineering', 'uni-university-of-genoa', 'master', 'engineering-technology', 'english', 2, 120, 'A Bachelor''s degree is required. Access is free, subject to verification of the admission requirements and personal academic background stated on the official programme page. Taught entirely in English in Genoa (degree class LM-32), linked to the EMARO/JEMARO international programmes.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://corsi.unige.it/en/corsi/11963', '2026/27', 'https://corsi.unige.it/en/corsi/11963', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-pisa-cs', 'pisa-msc-computer-science', 'MSc Computer Science', 'uni-university-of-pisa', 'master', 'computer-science-data', 'english', 2, 120, 'A Bachelor''s degree with an adequate computer-science background and English certification at B2 level are required. Non-EU candidates apply through the University of Pisa''s English-taught MSc application portal — see the official department page for the current call.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://didattica.di.unipi.it/en/master-programme-in-computer-science/', '2026/27', 'https://didattica.di.unipi.it/en/master-programme-in-computer-science/', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-siena-finance', 'siena-msc-finance', 'MSc Finance', 'uni-university-of-siena', 'master', 'business-management', 'english', 2, 120, 'A first degree (or equivalent) in economics or in a subject providing quantitative and financial skills, plus English at B2 level, is required. The Quantitative Finance curriculum is taught entirely in English (degree class LM-16) — see the official department page.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://www.disag.unisi.it/en/teaching/degree-courses/second-cycle-degree/finance', '2026/27', 'https://www.disag.unisi.it/en/teaching/degree-courses/second-cycle-degree/finance', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-verona-ds', 'verona-msc-data-science', 'MSc Data Science', 'uni-university-of-verona', 'master', 'computer-science-data', 'english', 2, 120, 'A Bachelor''s degree is required; admission is subject to the entry requirements published on the official programme page. Taught in English in Verona (degree class LM Data).', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://www.corsi.univr.it/?ent=cs&id=955&menu=ilcorso&tab=presentazione&lang=en', '2026/27', 'https://www.corsi.univr.it/?ent=cs&id=955&menu=ilcorso&tab=presentazione&lang=en', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-trieste-dsai', 'trieste-msc-data-science-artificial-intelligence', 'MSc Data Science and Artificial Intelligence', 'uni-university-of-trieste', 'master', 'computer-science-data', 'english', 2, 120, 'A Bachelor''s degree with at least 30 CFU in mathematics / computer-science disciplines (at least 9 CFU in mathematics) and English at B2 level are required. An Admission Board assesses curricular requirements and preparation — see the official ''How to apply'' page.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://degree.units.it/en/0320107313600001/how-apply', '2026/27', 'https://degree.units.it/en/0320107313600001/how-apply', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-pavia-harvey', 'pavia-medicine-surgery-harvey', 'Medicine and Surgery (Harvey) — Single-Cycle Master''s', 'uni-university-of-pavia', 'single_cycle', 'medicine-health', 'english', 6, 360, 'Secondary school diploma required. This is a six-year single-cycle Master''s degree taught in English with restricted access — admission is through the national admission test set by the annual ministerial call. See the official programme page for the current call.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://en.unipv.it/en/education/bachelors-and-masters-degree-programs/second-cycle-degree-course/medicine-and-surgery-0', '2026/27', 'https://en.unipv.it/en/education/bachelors-and-masters-degree-programs/second-cycle-degree-course/medicine-and-surgery-0', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-unibo-medicine', 'bologna-medicine-surgery', 'Medicine and Surgery — Single-Cycle Master''s', 'u-unibo', 'single_cycle', 'medicine-health', 'english', 6, 360, 'Secondary school diploma and English at B2 level are required. Access is restricted at national level: admission is through the entrance examination set each year by ministerial decree — see the official programme page and the annual call (degree class LM-41).', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://corsi.unibo.it/singlecycle/MedicineAndSurgery/overview', '2026/27', 'https://corsi.unibo.it/singlecycle/MedicineAndSurgery/overview', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-unitn-phd-iecs', 'trento-phd-information-engineering-computer-science', 'PhD in Information Engineering and Computer Science', 'u-unitn', 'phd', 'computer-science-data', 'english', 3, NULL, 'A Master''s degree (or a qualification giving access to PhD study) is required; candidates who will graduate by the date stated in the call may also apply. Admission is by the annual public selection (evaluation of qualifications) — most positions are covered by scholarships under the call. The programme''s official language is English.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'http://www.unitn.it/en/phd/information-engineering-and-computer-science', '2026/27', 'http://www.unitn.it/en/phd/information-engineering-and-computer-science', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-sapienza-phd-cs', 'sapienza-phd-computer-science', 'PhD in Computer Science', 'u-sapienza', 'phd', 'computer-science-data', 'english', 3, NULL, 'A Master''s degree is required. Admission is by competitive selection under Sapienza''s annual PhD call (qualifications and examination) — see the official PhD programme page for the current cycle, positions and scholarships.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://phd.uniroma1.it/web/COMPUTER-SCIENCE_nD3507_EN.aspx', '2026/27', 'https://phd.uniroma1.it/web/COMPUTER-SCIENCE_nD3507_EN.aspx', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-unibo-phd-dsc', 'bologna-phd-data-science-computation', 'PhD in Data Science and Computation', 'u-unibo', 'phd', 'computer-science-data', 'both', 3, 180, 'A second-level (Master''s) degree is required. Admission is by evaluation of qualifications and research proposal plus an oral examination, under the annual PhD call — see the official programme page for positions and scholarships. Working languages: English and Italian.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://phd.unibo.it/dsc/en/phd-programme/', '2026/27', 'https://phd.unibo.it/dsc/en/phd-programme/', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scholarships (id, slug, name, provider, kind, academic_year, geographic_eligibility, student_eligibility, degree_levels, requirements, documents, procedure, opens_note, closes_note, benefits, official_url, source_url, last_verified, verification_status, status) VALUES ('s-dsu', 'regional-dsu-scholarships', 'Regional Right-to-Study (DSU) Scholarships', 'Regional right-to-study agencies (e.g. ER.GO — Emilia-Romagna, DSU Toscana, ESU Padova, LazioDisco)', 'regional', '2026/27', 'Students enrolled at a university in the awarding region (each Italian region runs its own scheme).', 'Students enrolled (or enrolling) at an Italian university in the region, including international students, subject to the region''s income rules.', '{}'::text[], 'Awarded mainly on family income (ISEE-equivalent assessment for international students); continued eligibility usually requires earning a minimum number of credits (merit condition in later years). Exact thresholds are set by each region''s annual call.', ARRAY['Proof of enrolment or pre-enrolment at a university in the region','Family income and asset documentation (ISEE-equivalent for international students), typically translated and legalised','Identity documents and residence details as the regional call specifies']::text[], 'Apply through the regional agency''s online portal for the region where your university is located, within that region''s call deadline. Admission to the university and the DSU application are separate procedures.', 'Calls are usually published in summer before the academic year — verify on the regional agency site.', 'Set by each region in its annual call — check the regional agency for your university''s region.', 'Can combine a tuition-fee waiver with a cash grant and services such as student housing and canteens. Amounts and combinations vary by region and by the student''s income band — no amount is stated here because regions publish their own figures each year.', 'https://www.universitaly.it/', 'https://www.universitaly.it/', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scholarships (id, slug, name, provider, kind, academic_year, geographic_eligibility, student_eligibility, degree_levels, requirements, documents, procedure, opens_note, closes_note, benefits, official_url, source_url, last_verified, verification_status, status) VALUES ('s-iyt', 'invest-your-talent-in-italy', 'Invest Your Talent in Italy', 'Italian Ministry of Foreign Affairs (MAECI) with Uni-Italia and partner universities', 'national', '2026/27', 'Citizens of the countries listed in the current call — India has been included in recent editions; confirm for the current year.', 'International students from the countries listed in the current call, applying to eligible Master''s programmes in Italy.', '{}'::text[], 'Set by the annual call: typically a Bachelor''s degree, age and language conditions, and admission to an eligible programme. Read the current call text before applying.', ARRAY['Passport and academic certificates as the call specifies','Admission or pre-admission to an eligible programme','Language certificates where the call requires them']::text[], 'Apply on the official Invest Your Talent in Italy portal within the call window, for the eligible Master''s programmes listed that year.', 'The call is normally published once a year — check the official site for the current edition.', 'Published in the annual call on the official programme site.', 'Scholarship grant plus possible tuition arrangements with participating universities, as defined in each year''s official call. Amounts are published in the call — check the official site.', 'https://investyourtalent.esteri.it/', 'https://www.esteri.it/en/', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scholarships (id, slug, name, provider, kind, academic_year, geographic_eligibility, student_eligibility, degree_levels, requirements, documents, procedure, opens_note, closes_note, benefits, official_url, source_url, last_verified, verification_status, status) VALUES ('s-maeci', 'italian-government-scholarships-maeci', 'Italian Government Scholarships (MAECI)', 'Italian Ministry of Foreign Affairs and International Cooperation (MAECI)', 'national', '2026/27', 'Foreign citizens and Italians living abroad, per the current call.', 'International students applying for eligible study programmes in Italy, per the current call.', '{}'::text[], 'Defined in each annual call (degree level, age and language conditions vary). Always read the current call text.', ARRAY['As specified in the annual call — typically identity documents, academic records and the pre-enrolment reference']::text[], 'Apply through the official Study in Italy / MAECI application portal referenced in the call, after starting pre-enrolment on Universitaly.', 'Calls are published on the Ministry website — check for the current academic year.', 'Published in the annual call on the Ministry''s website.', 'Grants as defined in each annual call published by the Ministry. No amount is stated here — calls differ by year and grant type.', 'https://www.esteri.it/en/', 'https://www.esteri.it/en/', '2026-10-30', 'needs-review', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scholarships (id, slug, name, provider, kind, academic_year, geographic_eligibility, student_eligibility, degree_levels, requirements, documents, procedure, opens_note, closes_note, benefits, official_url, source_url, last_verified, verification_status, status) VALUES ('s-uni-waivers', 'university-fee-waivers-merit', 'University Fee Waivers & Merit Scholarships', 'Individual Italian universities', 'university', '2026/27', 'Students enrolled at the awarding university.', 'Enrolled students of the university, including international students, per each scheme''s rules.', '{}'::text[], 'Income-based tuition reduction (ISEE) is standard at public universities; merit scholarships have programme-specific rules published by each university.', ARRAY['University application or enrolment documents','Family income documentation for income-based reductions','Merit records where the award is merit-based']::text[], 'Follow the procedure on your university''s official fees and scholarships pages; income-based reductions usually require an ISEE-equivalent assessment.', 'Aligned with each university''s enrolment and fee calendar.', 'Set by each university — see the official fees and scholarships pages.', 'Varies by university and programme — may include partial or full tuition reduction and, for some merit awards, a grant. Details live on each university''s official fees and scholarships pages.', 'https://www.universitaly.it/', 'https://www.universitaly.it/', '2026-10-30', 'needs-review', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, category, question, answer, source_url, status) VALUES ('f-free', 'Getting started', 'Is the eligibility check really free?', 'Yes. The assessment on this website is free, runs in your browser, and shows your preliminary results before you are ever asked for contact details. Requesting a personalised review is always optional.', NULL, 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, category, question, answer, source_url, status) VALUES ('f-guarantee', 'Getting started', 'Can you guarantee my admission or scholarship?', 'No — and be cautious of anyone who does. Admissions are decided by universities, scholarships by regional agencies and universities, and visas by Italian authorities. We help you prepare a strong, correct application; outcomes are never guaranteed.', NULL, 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, category, question, answer, source_url, status) VALUES ('f-ielts', 'Language', 'Do I need IELTS to study in Italy?', 'Many English-taught programmes ask for proof of English around B2 level. Some accept IELTS or TOEFL, and some accept a Medium of Instruction (MOI) letter from your previous institution. Accepted proofs differ by programme — always check the official programme page.', NULL, 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, category, question, answer, source_url, status) VALUES ('f-dsu', 'Scholarships', 'What are DSU regional scholarships?', 'Diritto allo Studio Universitario (DSU) scholarships are run by Italy''s regions for students enrolled at universities in that region. They are assessed mainly on family income and can include a tuition-fee waiver, a cash grant and services like housing and canteens. Deadlines and income rules are set by each region.', 'https://www.universitaly.it/', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, category, question, answer, source_url, status) VALUES ('f-when', 'Planning', 'When should I start for the 2027–28 intake?', 'As early as you can. Programme application windows, scholarship calls and visa appointments run on separate calendars. Starting 9–12 months ahead leaves time for language tests, document legalisation and scholarship applications.', NULL, 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, category, question, answer, source_url, status) VALUES ('f-official', 'Official sources', 'Where does official information live?', 'Universitaly (the Italian Ministry''s portal for international students) is the official starting point for programme search and pre-enrolment. Visa rules are published by the Italian Ministry of Foreign Affairs and the Embassy of Italy in New Delhi.', 'https://www.universitaly.it/', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, category, question, answer, source_url, status) VALUES ('f-cost', 'Costs', 'How much does it cost to study in Italy for a year?', 'Use the cost calculator on this website to build your own estimate. As a rough guide, student living costs often fall around €7,000–€11,000 per year depending on the city and housing, plus tuition, which at public universities is income-based. Treat every figure as an estimate, never a quote.', NULL, 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, category, question, answer, source_url, status) VALUES ('f-work', 'Living in Italy', 'Can I work part-time while studying in Italy?', 'International students with a valid study residence permit are generally allowed part-time work up to 20 hours per week (with an annual cap). Rules can change — verify the current position on official Italian government sources before relying on work income.', NULL, 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, category, question, answer, source_url, status) VALUES ('f-docs', 'Documents', 'Which documents should I prepare first?', 'Start with your passport, academic transcripts and certificates, CV, statement of purpose, recommendation letters where required, and your language proof. For regional scholarships you will also need family income documents, usually translated and legalised. The document checklist page on this site walks through each item.', NULL, 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, category, question, answer, source_url, status) VALUES ('f-visa', 'Visa', 'How does the student visa process work?', 'After choosing a programme you complete pre-enrolment on the Universitaly portal, then apply for a study visa at the Italian Embassy or consulate responsible for your area, following their published checklist. N92 Edu-Italia helps you prepare and check the file, but the decision is made by the authorities.', 'https://ambnewdelhi.esteri.it/en/', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.calculator_settings (id, value) VALUES (1, '{"fxDate":"2026-10-30","fxRateInr":95,"monthly":{"accommodation":450,"food":280,"insurance":15,"materials":35,"personal":120,"transport":40},"notes":"Planning assumptions only — not official figures. Public-university tuition in Italy is income-based (ISEE); enter the fee from your programme''s official page. Living costs vary widely by city and lifestyle.","oneTime":{"permit":170,"setup":600,"travel":450},"tuitionAnnual":1600}'::jsonb) ON CONFLICT (id) DO NOTHING;
